'use strict';

// Generated by Clause Sonnet 5.5 / Refactored by HellXCore
// Which game is in front, if one (`game` in the window snapshot) 
// Linux looks the path of the program behind the window in front.
// A game is a program that sits in a launcher's library (Steam, Epic, GOG, Heroic);
// the game is the name of its folder there. The launchers themselves are not games.
// Only that folder name is ever passed on.
// A native game is its own program, so its path says it. A Windows game under Proton or Wine is
// "wine" to Linux, but the Windows path of the game is on its command line, and Steam's own
// processes above it (reaper, proton) carry it too; so the program's parents are looked at as well.
// Steam also gives such a window the class steam_app_<id>: its manifest names the folder.

const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const LIBRARIES = [
  /steamapps[\\/]common[\\/]([^\\/]+)[\\/]/i,
  /Epic Games[\\/]([^\\/]+)[\\/]/i,
  /Riot Games[\\/]([^\\/]+)[\\/]/i,
  /XboxGames[\\/]([^\\/]+)[\\/]/i,
  /GOG Galaxy[\\/]Games[\\/]([^\\/]+)[\\/]/i,
  /GOG Games[\\/]([^\\/]+)[\\/]/i,
  /Games[\\/]Heroic[\\/]([^\\/]+)[\\/]/i,
];
// The launchers, and what Steam keeps in the same folder as games but is no game: Proton itself (the
// program running a Windows game is wine, in Proton's folder), its runtimes, SteamVR
const NOT_GAME = /launcher|client|redistributable|steamworks|^proton\b|linux runtime|steamvr/i;
const PARENTS = 6; // how far up the parents to look

// the game named in a path or command line, or ''
function gameIn(text) {
  for (const re of LIBRARIES) {
    const m = re.exec(text);
    if (m && !NOT_GAME.test(m[1])) return m[1];
  }
  return '';
}

const read = (file) => {
  try {
    return fs.readFileSync(file, 'utf8');
  } catch {
    return '';
  }
};

// the parent of a process: the 4th field of /proc/<pid>/stat, after the name in parentheses
function parentOf(pid, proc) {
  const stat = read(path.join(proc, String(pid), 'stat'));
  const after = stat.slice(stat.lastIndexOf(')') + 2).split(' ');
  const ppid = Number(after[1]);
  return Number.isInteger(ppid) && ppid > 1 ? ppid : 0;
}

// Steam's folders, where its libraries are listed
function steamRoots(env = process.env, home = os.homedir()) {
  const data = env.XDG_DATA_HOME || path.join(home, '.local', 'share');
  const roots = [
    path.join(data, 'Steam'),
    path.join(home, '.steam', 'steam'),
    path.join(home, '.var', 'app', 'com.valvesoftware.Steam', '.local', 'share', 'Steam'),
  ];
  const libraries = new Set();
  for (const root of roots) {
    if (!fs.existsSync(path.join(root, 'steamapps'))) continue;
    libraries.add(root);
    for (const m of read(path.join(root, 'steamapps', 'libraryfolders.vdf')).matchAll(/"path"\s+"([^"]+)"/g)) libraries.add(path.normalize(m[1]));
  }
  return [...libraries];
}

// steam_app_730 -> the folder of that game, from its manifest ("installdir")
function steamFolder(appId, libraries) {
  for (const lib of libraries) {
    const acf = read(path.join(lib, 'steamapps', `appmanifest_${appId}.acf`));
    const dir = /"installdir"\s+"([^"]+)"/.exec(acf)?.[1];
    if (dir) return dir;
  }
  return '';
}

// The game behind the window of process `pid` (window class `cls`), or null. Cached by the caller.
function gameOf(pid, cls = '', { proc = '/proc', libraries = () => steamRoots() } = {}) {
  const app = /^steam_app_(\d+)$/i.exec(String(cls));
  if (app) {
    const folder = steamFolder(app[1], libraries());
    if (folder && !NOT_GAME.test(folder)) return folder;
  }
  let at = Number.isInteger(pid) && pid > 1 ? pid : 0;
  for (let depth = 0; at && depth <= PARENTS; depth++) {
    let exe = '';
    try {
      exe = fs.readlinkSync(path.join(proc, String(at), 'exe'));
    } catch {
      // not ours to look at, or gone
    }
    const cmd = read(path.join(proc, String(at), 'cmdline')).split('\0').join(' ');
    const found = gameIn(exe) || gameIn(cmd);
    if (found) return found;
    at = parentOf(at, proc);
  }
  return null;
}

// remembers the answer for as long as the same program is in front (the lookups read /proc)
function createGameWatcher(options) {
  let key = null;
  let game = null;
  return (pid, cls) => {
    const now = `${pid}|${cls}`;
    if (now !== key) {
      key = now;
      game = pid ? gameOf(pid, cls, options) : null;
    }
    return game;
  };
}

module.exports = { gameOf, gameIn, createGameWatcher, steamRoots, steamFolder };
